def _ua_device_name(ua):
    """User-Agent 문자열 → 사람이 읽는 기기명."""
    ua = str(ua or "")
    low = ua.lower()
    os_name = "기타"
    if "windows" in low:
        os_name = "Windows"
    elif "android" in low:
        os_name = "Android"
    elif "iphone" in low or "ipad" in low or "ios" in low:
        os_name = "iOS"
    elif "mac os" in low or "macintosh" in low:
        os_name = "macOS"
    elif "linux" in low:
        os_name = "Linux"
    browser = "브라우저"
    if "edg" in low:
        browser = "Edge"
    elif "whale" in low:
        browser = "Whale"
    elif "chrome" in low:
        browser = "Chrome"
    elif "safari" in low:
        browser = "Safari"
    elif "firefox" in low:
        browser = "Firefox"
    elif "kakao" in low:
        browser = "카카오"
    return f"{os_name} · {browser}"


