def _merch_guide(cfg):
    """cfg.guide 를 기본값과 병합해 반환(누락 키 자동 보충)."""
    g = cfg.get("guide")
    if not isinstance(g, dict):
        g = {}
    for k, v in DEFAULT_MERCH_GUIDE.items():
        g.setdefault(k, v)
    return g


def _merch_doc():
    """수품구매 문서 구조:
    {
      "products": [ {id, name, kind, price, stock, options:[..], image, desc,
                     active, created} ],
      "orders":   [ {id, productId, product, kind, unitPrice, qty, option,
                     total, buyerName, buyerNumber, phone, address,
                     shipMethod('현장구매'|'택배발송'|'기타'), shipNote,
                     paid(bool), memo, created} ],
      "config":   { "annualFee": 10000, "salesOpen": true,
                    "account": {bank,no,holder},
                    "guide": {title,membership,rules,sets,notes,updated}, "updated" }
    }
    """
    d = _load_json(MERCH_FILE, {})
    if not isinstance(d, dict):
        d = {}
    d.setdefault("products", [])
    d.setdefault("orders", [])

    # ── [버그수정 2026-11-20] 기존 주문에 상품 이미지 **백필** ────────────
    #  ## 증상
    #   주문상세 화면에서 상품 이미지가 전부 안 보였다.
    #
    #  ## 원인
    #   주문 생성 시 항목 dict 에 image 를 넣지 않았다(위 생성부에서 수정함).
    #   그래서 저장된 주문 62건 전부에 `image` 키가 아예 없었다.
    #   상품 카탈로그(products)에만 이미지가 있었다.
    #
    #  ## 왜 읽을 때 보완하나
    #   이미 저장된 주문을 일괄 수정하려면 DB 를 직접 고쳐야 하는데,
    #   그러면 되돌릴 수 없는 쓰기가 된다. 읽기 시점 보완은
    #   · 이미지가 **비어 있는 항목만** 채우고 (값이 있으면 건드리지 않음)
    #   · productId 로 현재 상품을 찾아 채우며
    #   · 상품이 삭제됐으면 그냥 넘어간다 (예외 없음)
    #   → 안전하고, 다음 저장 때 자연스럽게 영구 반영된다.
    try:
        _pmap = {}
        for _p in (d.get("products") or []):
            if not isinstance(_p, dict):
                continue
            _pid = str(_p.get("id", "") or "")
            if _pid:
                _pmap[_pid] = str(_p.get("image", "") or "")
        if _pmap:
            _filled = 0
            for _o in (d.get("orders") or []):
                if not isinstance(_o, dict):
                    continue
                if str(_o.get("image", "") or ""):
                    continue          # 이미 있으면 그대로 둔다
                _img = _pmap.get(str(_o.get("productId", "") or ""), "")
                if _img:
                    _o["image"] = _img
                    _filled += 1
            if _filled:
                print("[merch] 주문 %d건에 상품 이미지 백필" % _filled)
    except Exception as _e:
        print("[merch] 이미지 백필 건너뜀:", _e)

    cfg = d.get("config")
    if not isinstance(cfg, dict):
        cfg = {}
    cfg.setdefault("annualFee", 10000)
    cfg.setdefault("salesOpen", True)
    acc = cfg.get("account")
    if not isinstance(acc, dict):
        acc = {}
    acc.setdefault("bank", "우리은행")
    acc.setdefault("no", "1005 102 281143")
    acc.setdefault("holder", "한국범스카우트중앙회")
    acc.setdefault("shipFee", 5000)
    cfg["account"] = acc
    cfg["guide"] = _merch_guide(cfg)
    d["config"] = cfg
    before_oo = list(d.get("orderOrder", []))
    _merch_doc_defaults(d)
    # 같은 배치(구매자·시각 동일) 기존 주문 자동 통합 — 파편화된 주문번호 정리
    _merch_unify_same_batch(d)
    # orderOrder 정합화(누락분 보충 + 통합/삭제로 사라진 stale 키 제거)
    _merch_rebuild_order(d)
    if d.get("orderOrder") != before_oo:
        try:
            _save_json(MERCH_FILE, d)
        except Exception as e:
            print("merch orderOrder save fail", e)
    if _merch_seed_once(d):
        # 최초 시드 결과를 파일에 영구 저장 (다음 조회부터 유지)
        try:
            _save_json(MERCH_FILE, d)
        except Exception as e:
            print("merch seed save fail", e)
    if _merch_seed_supplies_once(d):
        try:
            _save_json(MERCH_FILE, d)
        except Exception as e:
            print("supplies seed save fail", e)
    if _seed_makers_once(d):
        try:
            _save_json(MERCH_FILE, d)
        except Exception as e:
            print("makers seed save fail", e)
    if _seed_purchases_once(d):
        try:
            _save_json(MERCH_FILE, d)
        except Exception as e:
            print("purchases seed save fail", e)
    return d


def _merch_supplies_sorted(doc):
    """suppliesOrder(비품 id 배열) 기준으로 비품을 정렬해 반환."""
    items = list(doc.get("supplies", []))
    order = doc.get("suppliesOrder", [])
    pos = {str(k): i for i, k in enumerate(order)}
    return sorted(items, key=lambda p: pos.get(str(p.get("id")), 10 ** 9))


def _merch_plans_sorted(doc):
    """plansOrder(기획 id 배열) 기준으로 기획실 아이템을 정렬해 반환."""
    items = list(doc.get("plans", []))
    order = doc.get("plansOrder", [])
    pos = {str(k): i for i, k in enumerate(order)}
    return sorted(items, key=lambda p: pos.get(str(p.get("id")), 10 ** 9))


def _merch_survey_applicants(doc, plan_id):
    """특정 기획 아이템의 수요조사 신청자 명단(순번 포함) 및 최소수량 대비 현황."""
    plan = next((x for x in doc.get("plans", [])
                 if str(x.get("id")) == str(plan_id)), None)
    if not plan:
        return None
    apps = plan.get("applicants", [])
    if not isinstance(apps, list):
        apps = []
    minimum = int(plan.get("minQty", 0) or 0)
    return {
        "planId": str(plan_id),
        "name": plan.get("name", ""),
        "minimum": minimum,
        "count": len(apps),
        "applicants": apps,
    }


def _merch_save(doc):
    _save_json(MERCH_FILE, doc)


def _merch_notify_orders(orders, order_no=""):
    """[요구 2026-11-04] 수품구매(굿즈) 주문 → 관리자 이상 알림 큐에 적재.

    ## 왜 필요했나 (실측 사고)
     요구: "수품구매 요청이 오면 알림버튼이 오던 기능이 작동하지 않았음"
     → 실은 **알림을 만드는 코드가 아예 없었다.**
       NOTIFY_FILE(notify.json) 생산자는 게시글·자료가져오기 둘뿐이었고
       `/api/merch/order` 는 `_merch_save(doc)` 만 호출했다.
       2026.11.02 박다운 주문 4건(주문번호 261102-10:32:06-박다운-0008)도
       큐에 흔적이 0건이었던 이유다.

    ## 규칙
     · 장바구니(배치) 주문은 여러 줄이 **하나의 주문번호**를 공유하므로
       알림도 1건으로 묶는다(4줄 주문 → 알림 4개 스팸 방지).
     · 단일 품목 주문은 그대로 1건.
     · 실패해도 주문 응답을 막지 않는다.
    """
    try:
        rows = [o for o in (orders or []) if isinstance(o, dict)]
        if not rows:
            return None
        buyer = str(rows[0].get("buyerName", "") or "").strip() or "비회원"
        phone = str(rows[0].get("phone", "") or "").strip()
        no = str(order_no or rows[0].get("orderNo", "") or "").strip()
        grand = 0
        for o in rows:
            try:
                grand += int(o.get("grandTotal", 0) or 0)
            except Exception:
                pass
        first = str(rows[0].get("product", "") or "")
        if len(rows) > 1:
            summary = "%s 외 %d건" % (first, len(rows) - 1)
        else:
            try:
                qty = int(rows[0].get("qty", 1) or 1)
            except Exception:
                qty = 1
            summary = first if qty <= 1 else "%s × %d" % (first, qty)
        title = "새 수품구매 주문 — %s" % buyer
        text = "%s님이 %s 을(를) 주문했습니다. 총 %s원" % (
            buyer, summary, format(grand, ","))
        if no:
            text += " (주문번호 %s)" % no
        return _notify_admin(
            "order",
            title,
            text,
            category="수품구매",
            author=buyer,
            orderNo=no,
            buyerName=buyer,
            phone=phone,
            amount=grand,
            itemCount=len(rows),
            orderIds=[str(o.get("id", "") or "") for o in rows],
        )
    except Exception as _e:
        print("[notify] 주문 알림 실패: %s" % _e)
        return None


