def _merch_seed_once(doc):
    """기본 수품목록을 시드한다.
    - 시드 전용 상품('seeded':true)은 버전이 바뀌면 새 기본목록으로 교체.
    - 관리자가 직접 추가한 상품('seeded' 없음)은 그대로 보존.
    - ★중요: 시드 상품이라도 사용자가 편집한 필드(설명·가격·이미지·이름·옵션
      등)는 이름 기준으로 보존한다. (기본 desc 갱신이 사용자 편집을 덮어써
      설명이 초기화되던 문제 방지 — turn12 수정)
    실제로 시드/갱신했으면 True 반환.
    """
    cfg = doc.get("config", {})
    cur = int(cfg.get("seedVersion", 0) or 0)
    if cur == MERCH_SEED_VERSION:
        return False
    now = _now_stamp()
    prev_products = doc.get("products", [])
    # 관리자 추가 상품(seeded 아님)은 무조건 보존
    kept = [p for p in prev_products
            if isinstance(p, dict) and p.get("seeded") is not True]
    # 기존 시드 상품 → 이름 기준 맵 (사용자 편집 보존용)
    prev_seeded = {}
    for p in prev_products:
        if isinstance(p, dict) and p.get("seeded") is True:
            nm = str(p.get("name", "") or "").strip()
            if nm:
                prev_seeded[nm] = p
    prods = list(kept)
    for base in DEFAULT_MERCH_PRODUCTS:
        p = dict(base)
        nm = str(base.get("name", "") or "").strip()
        prev = prev_seeded.get(nm)
        p["id"] = (str(prev.get("id")) if prev and prev.get("id")
                   else "pr" + _secrets.token_urlsafe(5))
        # 사용자 편집 가능 필드는 기존 값이 있으면 보존 (덮어쓰기 방지)
        _preserve = ("desc", "name", "price", "kind", "stock", "options",
                     "image", "active", "cost", "created", "size",
                     "makerId", "specList", "quoteFile", "quoteFileName",
                     "madeDate", "forSale", "soldStart", "soldBase",
                     "category")
        if prev:
            for f in _preserve:
                if f in prev and prev.get(f) not in (None, ""):
                    p[f] = prev[f]
        p.setdefault("image", "")
        p.setdefault("size", "")
        p.setdefault("makerId", "")
        p.setdefault("active", True)
        p.setdefault("created", now)
        p["seeded"] = True
        prods.append(p)
    doc["products"] = prods
    cfg["seeded"] = True
    cfg["seedVersion"] = MERCH_SEED_VERSION
    doc["config"] = cfg
    return True


def _merch_member(ident):
    return _ev_member_by_ident(ident)


def _merch_fee_paid(ident, year=None):
    """연회비 납부 여부(평생회원은 항상 납부 처리)."""
    m = _merch_member(ident)
    if not m:
        return False, None
    if m.get("lifetimeMember") is True:
        return True, m
    fy = m.get("feeYears")
    if not isinstance(fy, dict):
        fy = {}
    yr = year or str(datetime.datetime.now().year)
    paid = fy.get(yr) is True or fy.get(yr + "년") is True
    if not paid:
        # paidYears 호환: 값 true 인 키에서 숫자 추출
        for k, v in fy.items():
            if v is True and re.sub(r"[^0-9]", "", str(k)) == re.sub(r"[^0-9]", "", yr):
                paid = True
                break
    return bool(paid), m


# ==================== 수품 판매관리 확장 (상태·예약·제작자·공여·재고) ====================
# 주문 진행 상태(파이프라인) — 개인 프로필 진행 바차트에 사용
MERCH_ORDER_STATUSES = ["입금확인중", "입금확인", "상품준비중", "택배발송준비중",
                        "택배발송", "배송완료", "현장수령완료", "주문취소"]
# 예약(수요조사) 상태 — 제작 여부 판단
MERCH_RESERVE_STATUSES = ["예약접수", "제작검토", "제작확정", "제작중", "입고완료", "취소"]


def _merch_status_idx(status, pipeline=None):
    pipeline = pipeline or MERCH_ORDER_STATUSES
    try:
        return pipeline.index(str(status))
    except ValueError:
        return 0


def _merch_name_short(name):
    """주문번호용 주문자 약자(성 제외 이름 2자, 짧으면 그대로)."""
    n = re.sub(r"\s+", "", str(name or ""))
    if not n:
        return "미상"
    if len(n) >= 3:
        return n[-2:]
    return n


def _merch_parse_dt(created):
    """'created' 문자열을 datetime 으로 파싱(초 포함/미포함 모두 허용)."""
    s = str(created or "").strip()
    for fmt in ("%Y.%m.%d %H:%M:%S", "%Y.%m.%d %H:%M"):
        try:
            return datetime.datetime.strptime(s, fmt)
        except Exception:
            continue
    return datetime.datetime.now()


def _merch_make_order_no(name, created, count):
    """주문번호 생성: {YYMMDD}-{HH:MM:SS}-{주문자}-{NNNN}
    예) 260928-18:55:30-이승준-0010  → 날짜·시간·주문자·아이템 수를 모두 유추 가능.
    'count' = 한 주문번호로 함께 구매한 아이템 수(장바구니 10개 → 0010)."""
    dt = _merch_parse_dt(created)
    ymd = dt.strftime("%y%m%d")
    hms = dt.strftime("%H:%M:%S")
    nm = re.sub(r"\s+", "", str(name or "")) or "미상"
    nm = nm[:10]
    try:
        cnt = int(count or 0)
    except Exception:
        cnt = 0
    return "%s-%s-%s-%04d" % (ymd, hms, nm, cnt)


def _merch_assign_no(doc, rec, count=None):
    """레코드에 중복 없는 주문번호(orderNo)를 부여하고 반환."""
    if rec.get("orderNo"):
        return rec["orderNo"]
    if count is None:
        cnt = rec.get("itemCount", rec.get("lineCount", 0))
        if not cnt:
            cnt = len(rec.get("lines", [])) or rec.get("qty", 0) or 0
    else:
        cnt = count
    base = _merch_make_order_no(rec.get("buyerName"), rec.get("created"), cnt)
    used = set()
    for o in doc.get("orders", []):
        if isinstance(o, dict) and o.get("orderNo"):
            used.add(str(o["orderNo"]))
    for r in doc.get("reservations", []):
        if isinstance(r, dict) and r.get("orderNo"):
            used.add(str(r["orderNo"]))
    no = base
    i = 2
    while no in used:
        no = "%s(%d)" % (base, i)
        i += 1
    rec["orderNo"] = no
    return no


def _merch_products_sorted(doc):
    """productOrder(상품 id 배열) 기준으로 상품을 정렬해 반환한다.
    목록에 없는 상품은 뒤에 원래 순서대로 붙인다."""
    prods = list(doc.get("products", []))
    order = doc.get("productOrder", [])
    pos = {str(k): i for i, k in enumerate(order)}
    return sorted(prods, key=lambda p: pos.get(str(p.get("id")), 10 ** 9))


def _norm_spec_list(v):
    """견적서 기반 세부항목(사양/옵션) 리스트를 정규화한다.
    각 항목은 {label, value, note} 형태(모두 문자열). 최대 60개·길이 제한."""
    out = []
    if not isinstance(v, list):
        return out
    for it in v[:60]:
        if not isinstance(it, dict):
            # "라벨: 값" 문자열도 허용
            s = str(it or "").strip()
            if not s:
                continue
            if ":" in s:
                a, b = s.split(":", 1)
                out.append({"label": a.strip()[:40],
                            "value": b.strip()[:120], "note": ""})
            else:
                out.append({"label": s[:40], "value": "", "note": ""})
            continue
        label = str(it.get("label", "") or "")[:40]
        value = str(it.get("value", "") or "")[:120]
        note = str(it.get("note", "") or "")[:200]
        if not (label or value or note):
            continue
        out.append({"label": label, "value": value, "note": note})
    return out


def _merch_doc_defaults(doc):
    """확장 필드 기본값 보장(예약/제작자/공여/재고/공지)."""
    doc.setdefault("orders", [])
    doc.setdefault("reservations", [])
    doc.setdefault("makers", [])
    doc.setdefault("stockLog", [])
    doc.setdefault("donations", [])
    doc.setdefault("orderOrder", [])   # 표시 순서(주문번호/번들키 배열, 앞=최신)
    doc.setdefault("productOrder", [])  # 상품 표시 순서(상품 id 배열, 앞=먼저)
    doc.setdefault("supplies", [])      # 중앙회 비품 재고 리스트(품명/수량/비고/갱신·확인 이력)
    doc.setdefault("suppliesOrder", [])  # 비품 표시 순서(비품 id 배열, 앞=먼저)
    doc.setdefault("purchases", [])      # 물건 결제(범중앙회 물건 구매/결제 내역)
    doc.setdefault("purchasesOrder", [])  # 물건 결제 표시 순서
    doc.setdefault("plans", [])          # 기획실 아이템(사진/설명/메모/가격/동영상/기획자 등)
    doc.setdefault("plansOrder", [])     # 기획실 표시 순서(기획 id 배열, 앞=먼저)
    doc.setdefault("bundles", [])      # 합친 주문 묶음 [{id,name,keys:[],created}]
    doc.setdefault("archive", [])      # 30일 경과 삭제분 영구 보전
    cfg = doc.get("config")
    if not isinstance(cfg, dict):
        cfg = {}
    cfg.setdefault("notices", "수품 구매 시 아래 유의사항을 반드시 확인해 주세요.")
    cfg.setdefault("annualFeeRequired", False)  # 엄격모드(True): 연회비 미납 시 주문 차단
    cfg.setdefault("reserveMode", False)        # 예약/수요조사 모드 전체 ON/OFF
    # 제작자 견적서/사업자등록증 파일 열람·다운로드 권한(마스터 전용이 기본).
    #  관리자(app) 접근 허용 여부를 마스터가 on/off 한다(테스트 후 개방용).
    cfg.setdefault("makerFileAdminAllowed", False)
    # 견적서 기반 판매상품 세부항목(제작 견적→상품 옵션/사양) 마스터 전용.
    #  관리자 접근 허용 여부를 마스터가 on/off 한다.
    cfg.setdefault("quoteSpecAdminAllowed", False)
    cfg.setdefault("statuses", list(MERCH_ORDER_STATUSES))
    cfg.setdefault("reserveStatuses", list(MERCH_RESERVE_STATUSES))
    doc["config"] = cfg
    for o in doc.get("orders", []):
        if isinstance(o, dict):
            o.setdefault("status", "입금확인중")
            o.setdefault("statusHistory", [])
            o.setdefault("annualFeeAdded", 0)
            o.setdefault("contactId", "")
            o.setdefault("contactType", "")
            o.setdefault("orderNo", "")
            o.setdefault("deleted", False)     # 소프트 삭제 여부
            o.setdefault("deletedAt", "")      # 삭제 시각(30일 후 완전삭제)
            o.setdefault("bundleId", "")       # 합쳐진 묶음 id(없으면 빈값)
    for r in doc.get("reservations", []):
        if isinstance(r, dict):
            r.setdefault("status", "예약접수")
            r.setdefault("statusHistory", [])
            r.setdefault("orderNo", "")
            r.setdefault("deleted", False)
            r.setdefault("deletedAt", "")
    for pr in doc.get("products", []):
        if isinstance(pr, dict):
            pr.setdefault("credentialOnly", False)  # 인가자 전용 여부
    # 주문번호 일괄 부여(기존 데이터 마이그레이션)
    for o in doc.get("orders", []):
        if isinstance(o, dict) and not o.get("orderNo"):
            _merch_assign_no(doc, o)
    for r in doc.get("reservations", []):
        if isinstance(r, dict) and not r.get("orderNo"):
            _merch_assign_no(doc, r)
    # 표시 순서 배열에 누락분 보충(최신순)
    _merch_rebuild_order(doc)
    return doc


def _merch_group_key(rec):
    """표시 그룹 키 — 합쳐진 주문은 bundleId, 아니면 orderNo."""
    b = str(rec.get("bundleId", "") or "").strip()
    if b:
        return "B:" + b
    no = str(rec.get("orderNo", "") or "").strip()
    return no if no else "#" + str(rec.get("id", ""))


def _merch_unify_same_batch(doc):
    """같은 구매자·같은 시각(생성 분)에 흩어진 기존 주문들을 하나의 주문번호로 통합.

    장바구니 일괄 주문 기능 도입 이전, 품목마다 별도 주문번호로 생성된 과거
    데이터를 자동 정리한다. (bundleId 로 이미 묶였거나 삭제분은 건드리지 않음.)
    """
    orders = doc.get("orders", [])
    groups = {}
    for o in orders:
        if not isinstance(o, dict):
            continue
        if o.get("deleted") is True or str(o.get("bundleId", "")).strip():
            continue
        buyer = re.sub(r"[^0-9]", "", str(o.get("buyerNumber", "") or ""))
        if not buyer:
            buyer = str(o.get("phone", "") or "")
        created = str(o.get("created", "") or "").strip()
        if not buyer or not created:
            continue
        groups.setdefault((buyer, created), []).append(o)
    changed = False
    for (buyer, created), arr in groups.items():
        if len(arr) < 2:
            continue
        # 대표 주문번호: 이미 번호가 있는 첫 항목 것을 공유(없으면 신규 부여)
        rep = next((x for x in arr if str(x.get("orderNo", "")).strip()), None)
        if rep is None:
            rep = arr[0]
            _merch_assign_no(doc, rep)
        shared = str(rep.get("orderNo", "")).strip()
        for x in arr:
            if str(x.get("orderNo", "")).strip() != shared:
                x["orderNo"] = shared
                changed = True
    return changed


def _merch_rebuild_order(doc):
    """orderOrder 배열을 문서의 그룹키들과 정합화(누락분 앞에 추가, 유효분 유지)."""
    all_recs = list(doc.get("orders", [])) + list(doc.get("reservations", []))
    # 현재 문서에 실제 존재하는 그룹키 집합 (통합/삭제로 사라진 stale 키 제거용)
    valid = set()
    for rec in all_recs:
        if isinstance(rec, dict) and rec.get("deleted") is not True:
            valid.add(_merch_group_key(rec))
    order = [
        k for k in doc.get("orderOrder", [])
        if isinstance(k, str) and k in valid
    ]
    seen = set(order)
    # 새로 생긴 그룹키(아직 배열에 없는 것)를 최신순으로 앞에 추가
    fresh = []
    all_recs.sort(key=lambda x: str(x.get("created", "")), reverse=True)
    for rec in all_recs:
        if not isinstance(rec, dict) or rec.get("deleted") is True:
            continue
        k = _merch_group_key(rec)
        if k not in seen:
            fresh.append(k)
            seen.add(k)
    doc["orderOrder"] = fresh + order
    return doc



def _merch_attach_to_member(ident, oid, kind="order"):
    """주문/예약/사전신청 id를 회원 프로필 수품 내역에 부착(중복 방지). 반환: 부착 성공 여부."""
    d = re.sub(r"[^0-9]", "", str(ident or ""))
    if not d or not oid:
        return False
    key = ("merchReservations" if kind == "reservation"
           else ("merchSurveys" if kind == "survey" else "merchOrders"))
    with _MEMBER_WRITE_LOCK:
        members = _ev_members()
        for i, m in enumerate(members):
            mn = re.sub(r"[^0-9]", "", str(m.get("number", "")))
            mp = re.sub(r"[^0-9]", "",
                        str(m.get("accessPhone") or m.get("phone") or ""))
            if d in (mn, mp):
                lst = m.get(key)
                if not isinstance(lst, list):
                    lst = []
                if oid not in lst:
                    lst.append(oid)
                m[key] = lst
                members[i] = m
                _save_json(DB_FILE, members)
                _touch_meta({"updatedBy": "merch"})
                return True
    return False


def _merch_detach_from_member(ident, oid, kind="order"):
    """회원 프로필에서 주문/예약/사전신청 id 제거(주문 삭제 시)."""
    d = re.sub(r"[^0-9]", "", str(ident or ""))
    if not d or not oid:
        return
    key = ("merchReservations" if kind == "reservation"
           else ("merchSurveys" if kind == "survey" else "merchOrders"))
    with _MEMBER_WRITE_LOCK:
        members = _ev_members()
        hit = False
        for i, m in enumerate(members):
            mn = re.sub(r"[^0-9]", "", str(m.get("number", "")))
            mp = re.sub(r"[^0-9]", "",
                        str(m.get("accessPhone") or m.get("phone") or ""))
            if d in (mn, mp):
                lst = m.get(key)
                if isinstance(lst, list) and oid in lst:
                    lst.remove(oid)
                    m[key] = lst
                    members[i] = m
                    hit = True
        if hit:
            _save_json(DB_FILE, members)
            _touch_meta({"updatedBy": "merch-del"})


def _merch_ensure_regular(phone, name="", email=""):
    """전화번호 기준 비인가(일반)회원 자동 생성/조회. 반환: 식별번호(숫자)."""
    d = re.sub(r"[^0-9]", "", str(phone or ""))
    if not d:
        return ""
    with _MEMBER_WRITE_LOCK:
        members = _ev_members()
        for m in members:
            mp = re.sub(r"[^0-9]", "",
                        str(m.get("accessPhone") or m.get("phone") or ""))
            if mp and mp == d:
                return re.sub(r"[^0-9]", "", str(m.get("number", ""))) or d
        existing = {re.sub(r"[^0-9]", "", str(x.get("number", "")))
                    for x in members}
        # 번호 재사용 금지: 기존 9000xx 최대값 + 1 부터 부여한다.
        #  (중간 번호가 비어도 재사용하지 않음 → 과거 주문/예약의 contactId 가
        #   다른 신규 회원에게 승계되어 타인 내역이 노출되는 보안 사고 방지)
        mx = 900000
        for x in members:
            n = re.sub(r"[^0-9]", "", str(x.get("number", "")))
            if n.startswith("9000") and len(n) >= 6:
                try:
                    mx = max(mx, int(n))
                except Exception:
                    pass
        newno = ""
        for cand in range(mx + 1, mx + 1 + max(1, len(members) + 10)):
            if str(cand) not in existing:
                newno = str(cand)
                break
        if not newno:
            newno = str(mx + 1)
        rec = {
            "id": "guest_" + newno,
            "number": newno,
            "name": str(name or "").strip() or "비인가 구매자",
            "unit": "", "league": "",
            "phone": d, "accessPhone": d, "loginId": d,
            "email": str(email or "")[:80],
            "isRegular": True,
            "personalPassword": _ev_phone_last4(d),
            "approvalStatus": "pending",
            "approvalAt": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "merchOrders": [],
        }
        members.append(rec)
        _save_json(DB_FILE, members)
        _touch_meta({"count": len(members), "updatedBy": "merch_guest"})
        return newno


def _merch_resolve_contact(num, phone, name="", email=""):
    """주문자 식별: 인가번호 우선, 없으면 전화로 비인가 자동생성.
    반환: (contactId, contactType('member'|'regular'|''))"""
    n = re.sub(r"[^0-9]", "", str(num or ""))
    p = re.sub(r"[^0-9]", "", str(phone or ""))
    if n:
        m = _ev_member_by_ident(n)
        if m:
            mno = re.sub(r"[^0-9]", "", str(m.get("number", ""))) or n
            return mno, ("regular" if m.get("isRegular") else "member")
    if p:
        # 비인가(전화) 회원은 자동생성/조회하여 '회원번호'를 contactId 로 사용한다.
        #  → 개인프로필이 회원번호로 조회해도 본인 주문이 정확히 매칭된다.
        m = _ev_member_by_ident(p)
        if m:
            mno = re.sub(r"[^0-9]", "", str(m.get("number", "")))
            if mno:
                return mno, ("regular" if m.get("isRegular") else "member")
        no = _merch_ensure_regular(p, name, email)
        if no:
            return re.sub(r"[^0-9]", "", str(no)), "regular"
    return n, ""


def _merch_json_product(pr):
    out = {k: pr.get(k) for k in
           ("id", "name", "kind", "price", "stock", "sellableStock",
            "options", "image",
            "desc", "active", "makerId", "size")}
    # 각인 메달(멘토/페런츠)은 수여받는 사람(수령인) 정보 입력이 필수 → 프런트에서 폼 노출.
    out["recipientKind"] = _medal_recipient_kind(pr.get("name", ""))
    return out


def _medal_recipient_kind(name):
    """각인 메달 종류 판별 → 'mentor' | 'parent' | ''
    - 멘토 메달  : 수령인(멘토) 소속·이름·연락처 필요
    - 페런츠 메달: 수령인(보호자) 이름·연락처 필요
    (약장/패치 등 그 외 품목은 대상 아님)"""
    n = str(name or "")
    if "메달" not in n:
        return ""
    if "멘토" in n:
        return "mentor"
    if "페런츠" in n or "페렌츠" in n:
        return "parent"
    return ""


def _medal_recipient_ok(kind, rcp):
    """수령인 정보 유효성 검사(각인 메달 필수).
    요구: 범인가번호(number)는 멘토·페런츠 모두 필수 — 이 번호로 개인프로필
    (멘토·페런츠)에 수상/연동된다."""
    if kind not in ("mentor", "parent"):
        return True
    if not isinstance(rcp, dict):
        return False
    name = str(rcp.get("name", "") or "").strip()
    phone = str(rcp.get("phone", "") or "").strip()
    number = re.sub(r"[^0-9]", "", str(rcp.get("number", "") or ""))
    if kind == "mentor":
        unit = str(rcp.get("unit", "") or "").strip()
        return bool(unit and name and phone and number)
    return bool(name and phone and number)


def _medal_recipient_clean(rcp):
    """저장용 수령인 정보 정규화."""
    if not isinstance(rcp, dict):
        return {}
    return {
        "unit": str(rcp.get("unit", "") or "")[:80],
        "name": str(rcp.get("name", "") or "")[:40],
        "number": re.sub(r"[^0-9]", "", str(rcp.get("number", "") or ""))[:12],
        "phone": str(rcp.get("phone", "") or "")[:20],
    }


def _merch_sync_medal_recipients(buyer_ident, kind, recips):
    """각인 메달 수령인의 범인가번호로 **주문자 개인프로필**에 멘토·페런츠를
    추가하고, 수령인 인적사항을 link_profiles 에 등록한다.
      · kind 'mentor' → 주문자 mentors[] / 'parent' → parents[]
      · link_profiles[수령인번호] = {name, phone, unit, kind}  (없을 때만 생성)
    요구: "이 넘버로 개인프로필 멘토·페런츠에 추가"."""
    if kind not in ("mentor", "parent"):
        return
    buyer = re.sub(r"[^0-9]", "", str(buyer_ident or ""))
    nums = [re.sub(r"[^0-9]", "", str(r.get("number", "") or ""))
            for r in recips if isinstance(r, dict)]
    nums = [n for n in nums if n]
    if not nums:
        return
    # 1) 주문자(멘티/자녀) 프로필의 mentors/parents 에 수령인 번호 추가
    if buyer:
        with _MEMBER_WRITE_LOCK:
            members = _ev_members()
            hit = False
            for i, m in enumerate(members):
                num = re.sub(r"[^0-9]", "", str(m.get("number", "")))
                lid = re.sub(r"[^0-9]", "", str(m.get("loginId", "")))
                ph = re.sub(r"[^0-9]", "",
                            str(m.get("accessPhone") or m.get("phone") or ""))
                if buyer in (num, lid, ph):
                    field = "mentors" if kind == "mentor" else "parents"
                    cur = m.get(field)
                    if not isinstance(cur, list):
                        cur = []
                    added = False
                    for n in nums:
                        if n not in [str(x) for x in cur]:
                            cur.append(n)
                            added = True
                    m[field] = cur
                    # 새 연결이 실제로 추가된 경우에만 승인요청 상태로 전환하고,
                    # 요청방법을 '수품신청시'(merch)로 기록한다(요구).
                    if added:
                        m["linkApprovalStatus"] = "pending"
                        m["linkRequestSource"] = "merch"
                        _link_mark_request(m, None, default_source="merch")
                    members[i] = m
                    hit = True
                    break
            if hit:
                _save_json(DB_FILE, members)
    # 2) 수령인 인적사항을 link_profiles 에 등록 + **비인가(일반)회원 계정 자동생성**.
    #   요구: "수품구매시 입력한 멘토·페런츠 입력값으로 비인가 회원 아이디 자동생성"
    #         "서로간의 데이터가 연동 잘 되어야 함"
    #   → 수령인(멘토·페런츠)의 전화/이름으로 일반회원(서포터즈) 계정을 만들고,
    #     아이디(전화)·비밀번호(뒤4자리!@@)를 link_profiles 에 함께 기록한다.
    #     계정 생성은 _merch_ensure_regular 로 실제 member 레코드로 등록된다.
    try:
        profs = _link_profiles_load()
        changed = False
        for r in recips:
            if not isinstance(r, dict):
                continue
            n = re.sub(r"[^0-9]", "", str(r.get("number", "") or ""))
            ph = str(r.get("phone", "") or "")
            rec_name = str(r.get("name", "") or "")
            # (a) 수령인 비인가(일반)회원 계정 자동 생성/조회 — 전화번호 기준.
            #  🐞 2026-11-02 (build #571): 수령인이 **범인가자**면 전화번호 계정을
            #  만들지 않는다(그분은 이미 카드+로그인이 있다). 인가자 판정은
            #  인가번호가 members 명단에 실존하는지로 한다.
            _rec_is_cred = False
            if n:
                try:
                    _rec_is_cred = _is_tsak_credential(n)
                except Exception:
                    _rec_is_cred = False
            if ph.strip() and not _rec_is_cred:
                try:
                    _merch_ensure_regular(ph, rec_name, "")
                except Exception as _e:
                    print("medal recipient regular create fail", _e)
            # (b) 인적사항(프로필) 등록 — 인가번호가 있을 때만 키로 사용.
            if not n:
                continue
            # 종류별 복합키(멘토:<번호>/페런츠:<번호>)로 조회·생성.
            _pk = _link_key(kind, n)
            if _pk in profs and isinstance(profs[_pk], dict):
                # 이미 있으면 아이디/비번만 보정한다(기존 입력 보존).
                try:
                    if _rec_is_cred:
                        profs[_pk]["isScouter"] = True
                        if not re.sub(r"[^0-9]", "", str(
                                profs[_pk].get("scoutNo", "") or "")):
                            profs[_pk]["scoutNo"] = n
                        # 인가자는 전화번호 계정을 만들지 않는다.
                        profs[_pk]["loginId"] = ""
                        profs[_pk]["password"] = ""
                        changed = True
                    else:
                        _lid, _lpw = _gen_profile_credentials(ph, rec_name)
                        if _lid and not str(
                                profs[_pk].get("loginId") or "").strip():
                            profs[_pk]["loginId"] = _lid
                            profs[_pk]["password"] = _lpw
                            changed = True
                except Exception:
                    pass
                continue
            profs[_pk] = _link_profile_sanitize({
                "number": n,
                "name": rec_name,
                "phone": ph,
                "league": str(r.get("league", "") or ""),
                "unit": str(r.get("unit", "") or ""),
                "kind": kind,
                "isScouter": _rec_is_cred,
                "scoutNo": n if _rec_is_cred else "",
            })
            profs[_pk]["receiverNo"] = n
            try:
                # 인가자면 아이디/비번을 만들지 않는다(2026-11-02).
                _lid, _lpw = (("", "") if _rec_is_cred
                              else _gen_profile_credentials(ph, rec_name))
                if _lid:
                    profs[_pk]["loginId"] = _lid
                    profs[_pk]["password"] = _lpw
            except Exception:
                pass
            profs[_pk]["updatedAt"] = _now_stamp()
            changed = True
        if changed:
            with LOCK:
                _link_profiles_save(profs)
    except Exception as e:
        print("medal recipient link sync fail", e)


# ==========================================================================
# 멘토·페런츠·멘티 장부 — 요구:
#   "멘토장부, 페런츠 장부, 멘티장부 모두 존재해야함. 멘토·페런츠 장부에는
#    멘토메달, 멘토항건 구매여부, 시점도 표시함. 연차등록 여부도 표시함."
#  · 멘토/페런츠 = link_profiles.json(kind) 인적사항.
#  · 멘티       = 회원 명단 mentees[] 에서 파생(멘토=멘티=페런츠 연동).
#  · 멘토·페런츠메달 구매여부·시점 = merch.json 주문(recipientKind + 각인번호).
#  · 중앙회 항건  구매여부·시점 = merch.json 주문(상품명 '항건' + buyerNumber).
#  · 연차등록 여부 = 회원 feeYears(연회비 납부) / lifetimeMember.
# ==========================================================================
def _medal_ledger_map():
    """merch.json 주문 → {번호: {'mentor': [...], 'parent': [...], 'hangeon': [...]}}."""
    doc = _load_json(MERCH_FILE, {}) or {}
    out = {}

    def _slot(n):
        return out.setdefault(n, {"mentor": [], "parent": [], "hangeon": []})

    for o in (doc.get("orders") or []):
        if not isinstance(o, dict) or o.get("deleted") is True:
            continue
        created = str(o.get("created", "") or "")
        status = str(o.get("status", "") or "")
        prod = str(o.get("product", "") or "")
        kind = str(o.get("recipientKind") or "")
        # 각인 메달 — 수령인(각인) 번호 기준.
        if kind in ("mentor", "parent"):
            recips = o.get("recipients")
            if not isinstance(recips, list):
                recips = ([o.get("recipient")]
                          if isinstance(o.get("recipient"), dict) else [])
            for r in recips:
                if not isinstance(r, dict):
                    continue
                rno = re.sub(r"[^0-9]", "", str(r.get("number", "") or ""))
                if not rno:
                    continue
                _slot(rno)[kind].append({
                    "product": prod, "created": created, "status": status,
                    "qty": int(o.get("qty", 1) or 1),
                })
        # 중앙회 항건(넥커치프) — 구매자 기준.
        if "항건" in prod:
            bno = re.sub(r"[^0-9]", "", str(o.get("buyerNumber", "") or ""))
            if bno:
                _slot(bno)["hangeon"].append({
                    "product": prod, "created": created, "status": status,
                    "qty": int(o.get("qty", 1) or 1),
                })
    return out


def _ledger_annual(m):
    """연차등록 여부 — 연회비 납부(feeYears) 또는 평생회원 여부."""
    if not isinstance(m, dict) or not m:
        return {"status": "—", "life": False, "paidYears": [], "year": ""}
    fy = m.get("feeYears")
    paid = sorted([str(k) for k, v in fy.items() if v is True]) \
        if isinstance(fy, dict) else []
    life = m.get("lifetimeMember") is True
    if life:
        status = "평생회원"
    elif paid:
        status = "연차등록(" + paid[-1] + ")"
    else:
        status = "미등록"
    year = str(m.get("lifetimeSince") or (paid[-1] if paid else "") or "")
    return {"status": status, "life": life, "paidYears": paid, "year": year}


def _medal_summary(items):
    """구매 이력 목록 → {bought, at(최초 시점), count, status}."""
    if not items:
        return {"bought": False, "at": "", "count": 0, "status": ""}
    items2 = sorted(items, key=lambda x: str(x.get("created", "")))
    return {
        "bought": True,
        "at": str(items2[0].get("created", "") or ""),
        "count": len(items2),
        "status": str(items2[-1].get("status", "") or ""),
    }


def _link_ledger_entries(kind):
    """장부 엔트리 — kind: 'mentor' | 'parent' | 'mentee'."""
    profs = _link_profiles_load()
    medals = _medal_ledger_map()
    members = _ev_members()
    by_num = {}
    for m in members:
        if not isinstance(m, dict):
            continue
        n = re.sub(r"[^0-9]", "", str(m.get("number", "") or ""))
        if n:
            by_num[n] = m
    entries = []
    if kind in ("mentor", "parent"):
        for key, p in profs.items():
            if not isinstance(p, dict):
                continue
            if str(p.get("kind") or "mentor") != kind:
                continue
            num = re.sub(r"[^0-9]", "", str(p.get("number", "") or key))
            medal_items = medals.get(num, {}).get(kind, [])
            # 이 사람이 배출(멘토)·보호(페런츠)한 대원 수.
            links = 0
            for m in members:
                arr = m.get("mentors") if kind == "mentor" else m.get("parents")
                if num and num in [re.sub(r"[^0-9]", "", str(x))
                                   for x in (arr or [])]:
                    links += 1
            mm = by_num.get(num)
            entries.append({
                "number": num,
                "name": str(p.get("name", "") or ""),
                "phone": str(p.get("phone", "") or ""),
                "league": str(p.get("league", "") or ""),
                "unit": str(p.get("unit", "") or ""),
                "kind": kind,
                "kindLabel": "멘토" if kind == "mentor" else "페런츠",
                "loginId": str(p.get("loginId", "") or ""),
                "receiverNo": str(p.get("receiverNo", "") or ""),
                "created": str(p.get("updatedAt", "") or ""),
                "mentorMedal": _medal_summary(
                    medal_items if kind == "mentor" else []),
                "parentMedal": _medal_summary(
                    medal_items if kind == "parent" else []),
                "hangeon": _medal_summary(
                    medals.get(num, {}).get("hangeon", [])),
                "annual": _ledger_annual(mm) if mm
                else {"status": "—", "life": False, "paidYears": [], "year": ""},
                "links": links,
            })
    else:  # mentee — 회원 명단 mentees[] 파생.
        seen = set()
        for m in members:
            if m.get("isRegular") is True:
                continue
            for code in (m.get("mentees") or []):
                num = re.sub(r"[^0-9]", "", str(code))
                if not num or num in seen:
                    continue
                seen.add(num)
                mm = by_num.get(num) or {}
                entries.append({
                    "number": num,
                    "name": str(mm.get("name", "") or ""),
                    "phone": str(mm.get("phone", "") or ""),
                    "league": str(mm.get("league", "") or ""),
                    "unit": str(mm.get("unit", "") or ""),
                    "kind": "mentee",
                    "kindLabel": "멘티",
                    "loginId": str(mm.get("loginId", "") or ""),
                    "receiverNo": "",
                    "created": str(mm.get("date", "") or ""),
                    "mentorMedal": _medal_summary(
                        medals.get(num, {}).get("mentor", [])),
                    "parentMedal": _medal_summary(
                        medals.get(num, {}).get("parent", [])),
                    "hangeon": _medal_summary(
                        medals.get(num, {}).get("hangeon", [])),
                    "annual": _ledger_annual(mm),
                    "mentor": str(m.get("name", "") or ""),
                    "mentorNo": re.sub(r"[^0-9]", "",
                                       str(m.get("number", "") or "")),
                    "links": 0,
                })
    entries.sort(key=lambda x: str(x.get("name", "")))
    return entries


def _merch_mine(ident):
    """한 회원(인가번호/전화)의 주문/예약 내역 + 상태 파이프라인.
    삭제(소프트)된 주문은 구매자에게 노출하지 않는다."""
    d = re.sub(r"[^0-9]", "", str(ident or ""))
    doc = _merch_doc()
    orders, reserves = [], []
    for o in doc.get("orders", []):
        if o.get("deleted") is True:
            continue
        if _merch_match_ident(o, d):
            orders.append(o)
    for r in doc.get("reservations", []):
        if r.get("deleted") is True:
            continue
        if _merch_match_ident(r, d):
            reserves.append(r)
    orders.sort(key=lambda x: str(x.get("created", "")), reverse=True)
    reserves.sort(key=lambda x: str(x.get("created", "")), reverse=True)
    return orders, reserves


def _merch_mine_surveys(ident):
    """한 회원(인가번호/전화)이 사전신청한 수요조사 수품 목록 + 순번/최소제작수량.
    프로필의 '수품구매' 항목에 예약(사전신청) 수품을 노출하기 위함."""
    d = re.sub(r"[^0-9]", "", str(ident or ""))
    if not d:
        return []
    doc = _merch_doc()
    out = []
    for pl in _merch_plans_sorted(doc):
        apps = pl.get("applicants", [])
        if not isinstance(apps, list):
            continue
        mine = None
        for a in apps:
            if _merch_match_ident(
                    {"contactId": a.get("contactId", ""),
                     "buyerNumber": a.get("number", ""),
                     "phone": a.get("phone", "")}, d):
                mine = a
                break
        if mine is None:
            continue
        out.append({
            "planId": pl.get("id"),
            "name": pl.get("name", ""),
            "photo": pl.get("photo", ""),
            "price": int(pl.get("price", 0) or 0),
            "minQty": int(pl.get("minQty", 0) or 0),
            "progress": pl.get("progress", ""),
            "maker": pl.get("maker", ""),
            "surveyOpen": pl.get("surveyOpen") is True,
            "count": len(apps),
            "myNo": mine.get("no", 0),
            "memo": mine.get("memo", ""),
            "at": mine.get("at", ""),
        })
    return out


DELETED_KEEP_DAYS = 30


def _merch_purge_deleted(doc):
    """삭제 후 30일이 지난 주문/예약을 archive로 이동(영구 보전, 화면 비노출)."""
    now = datetime.datetime.now()
    keep_orders, archive = [], doc.get("archive", [])
    if not isinstance(archive, list):
        archive = []
    changed = False
    for o in doc.get("orders", []):
        if isinstance(o, dict) and o.get("deleted") is True and o.get("deletedAt"):
            try:
                dt = datetime.datetime.fromisoformat(str(o["deletedAt"]))
            except Exception:
                dt = now
            if (now - dt).days >= DELETED_KEEP_DAYS:
                o["_archivedAt"] = _now_stamp()
                archive.append(o)
                changed = True
                continue
        keep_orders.append(o)
    keep_res, forders = [], doc.get("orders", [])
    for r in doc.get("reservations", []):
        if isinstance(r, dict) and r.get("deleted") is True and r.get("deletedAt"):
            try:
                dt = datetime.datetime.fromisoformat(str(r["deletedAt"]))
            except Exception:
                dt = now
            if (now - dt).days >= DELETED_KEEP_DAYS:
                r["_archivedAt"] = _now_stamp()
                archive.append(r)
                changed = True
                continue
        keep_res.append(r)
    if changed:
        doc["orders"] = keep_orders
        doc["reservations"] = keep_res
        doc["archive"] = archive
        # 표시순서에서 아카이브된 그룹키 제거
        valid = set()
        for rec in keep_orders + keep_res:
            valid.add(_merch_group_key(rec))
        doc["orderOrder"] = [k for k in doc.get("orderOrder", []) if k in valid]
    return doc


_PH2NO_CACHE = {"ts": 0.0, "map": {}}


def _phone_owner_map():
    """전화번호 → 회원번호 맵 (TTL 캐시: NAS 재조회 최소화).
    매 호출마다 회원목록을 읽으면 느리므로(주문 조회 지연) 30초 캐시한다."""
    import time as _t
    now = _t.time()
    if _PH2NO_CACHE["map"] and (now - _PH2NO_CACHE["ts"] < 30):
        return _PH2NO_CACHE["map"]
    m = {}
    for mem in _ev_members():
        no = re.sub(r"[^0-9]", "", str(mem.get("number", "")))
        for f in ("phone", "accessPhone", "loginId"):
            p = re.sub(r"[^0-9]", "", str(mem.get(f, "") or ""))
            if p and p not in m:
                m[p] = no
    _PH2NO_CACHE["ts"] = now
    _PH2NO_CACHE["map"] = m
    return m


def _merch_match_ident(rec, d):
    """주문/예약 레코드가 식별자 d(숫자)의 소유인지 판정.

    보안 강화: 비인가(일반)회원 자동생성 번호(900001~)가 재사용되면 과거
    주문의 contactId 가 다른 신규 회원에게 승계되어 타인 내역이 노출된다.
    따라서 contactId 단독 일치만으로는 매칭하지 않고, 레코드의 전화번호로
    조회한 실제 소유자 번호가 contactId 와 일치할 때만 인정한다.
    (전화번호 직접 일치는 재사용과 무관하게 항상 신뢰한다.)
    """
    if not d:
        return False
    ci = re.sub(r"[^0-9]", "", str(rec.get("contactId", "")))
    bn = re.sub(r"[^0-9]", "", str(rec.get("buyerNumber", "")))
    ph = re.sub(r"[^0-9]", "", str(rec.get("phone", "")))
    # ① 전화번호 직접 일치 — 재사용 충돌과 무관하게 항상 신뢰.
    if d in (bn, ph):
        return True
    # ② contactId 일치 — 레코드 전화의 실제 소유자가 contactId 와 같을 때만.
    if ci and ci == d:
        order_ph = ph or bn
        if not order_ph:
            return True  # 전화정보 없음 → contactId 신뢰
        owner = _phone_owner_map().get(order_ph, order_ph)
        return owner == ci
    # ③ 회원번호(d)로 조회 — 레코드 전화의 실제 소유자가 d 이면 본인 주문.
    #    (주문 시 contactId 가 전화번호로 저장된 경우도 회원번호 로그인에서 인식)
    order_ph = ph or bn
    if order_ph:
        owner = _phone_owner_map().get(order_ph, order_ph)
        if owner and owner == d:
            return True
    return False


def _sellable_of(pr):
    """상품의 **판매가능재고**(쇼핑몰 노출 수량).

    · 직접입력 필드(sellableStock) — 기본 999. 미설정/빈값이면 999.
    · 음수는 0 으로 보정한다.
    """
    raw = pr.get("sellableStock")
    if raw is None or raw == "":
        return 999
    try:
        return max(0, int(raw))
    except Exception:
        return 999


def _merch_stats(doc):
    """누적판매·재고·예약 통계."""
    cfg = doc.get("config", {})
    orders = doc.get("orders", [])
    prods = doc.get("products", [])
    reserves = doc.get("reservations", [])
    total_sales = 0
    total_fee = 0
    by_status = {}
    by_product = {}
    by_month = {}
    sold_qty = {}
    by_name_qty = {}
    for o in orders:
        if not isinstance(o, dict):
            continue
        if o.get("deleted") is True:
            continue
        if str(o.get("status", "")) == "주문취소":
            continue
        t = int(o.get("total", 0) or 0)
        fee = int(o.get("annualFeeAdded", 0) or 0)
        total_sales += t
        total_fee += fee
        st = str(o.get("status", "입금확인중"))
        by_status[st] = by_status.get(st, 0) + 1
        nm = str(o.get("product", ""))
        b = by_product.setdefault(nm, {"qty": 0, "amount": 0})
        b["qty"] += int(o.get("qty", 0) or 0)
        b["amount"] += t
        sold_qty[str(o.get("productId", ""))] = \
            sold_qty.get(str(o.get("productId", "")), 0) + int(o.get("qty", 0) or 0)
        # 상품ID 없이 이름으로만 기록된 주문 폴백 집계용.
        nm_key = nm.strip()
        if nm_key:
            by_name_qty[nm_key] = by_name_qty.get(nm_key, 0) + \
                int(o.get("qty", 0) or 0)
        ym = str(o.get("created", ""))[:7]
        if ym:
            by_month[ym] = by_month.get(ym, 0) + t
    stock = []
    for pr in prods:
        pid = str(pr.get("id"))
        nm = str(pr.get("name", ""))
        sold = sold_qty.get(pid, 0)
        if sold == 0:
            sold = by_name_qty.get(nm.strip(), 0)
        # soldBase(기초 누적판매) — 인수인계 대장 등 기존 누적 + 앱 판매분.
        sold_live = int(pr.get("soldBase", 0) or 0) + sold
        stock.append({
            "id": pr.get("id"), "name": nm,
            "stock": int(pr.get("stock", 0) or 0),
            # 판매가능재고 — 수품구매(쇼핑몰)에 노출되는 판매 가능 수량.
            #  직접입력(기본 999). 미설정 상품은 999 로 간주한다.
            "sellableStock": int(_sellable_of(pr)),
            "sold": sold_live,
            "forSale": pr.get("forSale") is not False,
            "active": pr.get("active") is not False,
        })
    reserve_by_product = {}
    for r in reserves:
        if str(r.get("status", "")) == "취소":
            continue
        nm = str(r.get("product", ""))
        reserve_by_product[nm] = reserve_by_product.get(nm, 0) + \
            int(r.get("qty", 0) or 0)
    return {
        "orderCount": len([o for o in orders
                           if str(o.get("status", "")) != "주문취소"
                           and o.get("deleted") is not True]),
        "totalSales": total_sales,
        "totalAnnualFee": total_fee,
        "byStatus": by_status,
        "byProduct": by_product,
        "byMonth": dict(sorted(by_month.items())),
        "stock": stock,
        "reserveCount": len([r for r in reserves
                             if str(r.get("status", "")) != "취소"
                             and r.get("deleted") is not True]),
        "reserveByProduct": reserve_by_product,
    }


def _make_image_thumb2(src_bytes, year, title, name, sub="", max_side=480):
    """행사 항목 이미지 → JPEG 썸네일."""
    try:
        import io
        from PIL import Image, ImageOps
        im = Image.open(io.BytesIO(src_bytes))
        im = ImageOps.exif_transpose(im).convert("RGB")
        im.thumbnail((max_side, max_side))
        buf = io.BytesIO()
        im.save(buf, format="JPEG", quality=78, optimize=True)
        NAS.write(_ev_thumb_path(year, title, name, sub), buf.getvalue())
        return True
    except Exception as e:
        print("ev thumb fail", name, e)
        return None


def _make_video_thumb2(local_tmp_path, year, title, name, sub="", max_side=480):
    """행사 항목 동영상 → 첫 프레임 썸네일."""
    try:
        import subprocess, tempfile
        out = tempfile.NamedTemporaryFile(suffix=".jpg", delete=False).name
        subprocess.run(
            ["ffmpeg", "-y", "-ss", "0.5", "-i", local_tmp_path, "-frames:v", "1",
             "-vf", f"scale='min({max_side},iw)':-2", "-q:v", "4", out],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=60)
        if not os.path.exists(out) or os.path.getsize(out) == 0:
            return None
        with open(out, "rb") as f:
            data = f.read()
        try:
            os.unlink(out)
        except Exception:
            pass
        NAS.write(_ev_thumb_path(year, title, name, sub), data)
        return True
    except Exception as e:
        print("ev vthumb fail", name, e)
        return None


def _make_image_thumb3(src_bytes, year, title, space, name, sub="",
                       max_side=480):
    """space(key) 지정형 이미지 썸네일 생성 — media/expense 공용.

    기존 `_make_image_thumb2` 는 썸네일 경로에 매체(media) 하위폴더를 가정한다.
    이 함수는 `_ev_thumb_path_k` 로 space 를 구분해 저장하므로, 영수증·증빙사진
    도 사진과 똑같이 '원본과 분리된 최적 썸네일'을 갖는다.
    """
    try:
        import io
        from PIL import Image, ImageOps
        im = Image.open(io.BytesIO(src_bytes))
        im = ImageOps.exif_transpose(im).convert("RGB")
        im.thumbnail((max_side, max_side))
        buf = io.BytesIO()
        im.save(buf, format="JPEG", quality=82, optimize=True)
        _ev_ensure_thumb_dir(year, title)
        fp = _ev_thumb_path_k(year, title, space, name, sub)
        NAS.write(fp, buf.getvalue())
        try:
            _thumb_disk_put(year, title,
                            _ev_thumb_key_k(space, name, sub), buf.getvalue())
        except Exception:
            pass
        return True
    except Exception as e:
        print("thumb3 fail", name, e)
        return False


def _make_image_view3(src_bytes, year, title, space, name, sub="",
                      max_side=1600):
    """space(key) 지정형 '보기용 최적본' 생성."""
    try:
        import io
        from PIL import Image, ImageOps
        im = Image.open(io.BytesIO(src_bytes))
        im = ImageOps.exif_transpose(im).convert("RGB")
        im.thumbnail((max_side, max_side))
        buf = io.BytesIO()
        im.save(buf, format="JPEG", quality=85, optimize=True)
        try:
            _ev_mkdir_deep(_ev_view_dir(year, title))
        except Exception:
            pass
        fp = _ev_view_path_k(year, title, space, name, sub)
        NAS.write(fp, buf.getvalue())
        return True
    except Exception as e:
        print("view3 fail", name, e)
        return False


def _make_image_view2(src_bytes, year, title, name, sub="", max_side=1600):
    """사진 '최적 크기' 보기용 지연 생성본(1600px, 품질 85)."""
    try:
        import io
        from PIL import Image, ImageOps
        im = Image.open(io.BytesIO(src_bytes))
        im = ImageOps.exif_transpose(im).convert("RGB")
        im.thumbnail((max_side, max_side))
        buf = io.BytesIO()
        im.save(buf, format="JPEG", quality=85, optimize=True)
        vp = _ev_view_path(year, title, name, sub)
        d = vp.rsplit("/", 1)[0]
        _ev_mkdir_deep(d)
        NAS.write(vp, buf.getvalue())
        return True
    except Exception as e:
        print("view fail", name, e)
        return None


# ============ 행사 썸네일 일괄 백필(backfill) ============
# 기존 업로드분은 썸네일이 없어 첫 조회 시 서빙 경로에서 "지연 생성"된다.
# 그 비용(원격 NAS 원본 다운로드+PIL 리사이즈)이 목록 로딩을 매우 느리게
# 만들므로, 백그라운드 작업으로 미리 모든 썸네일을 만들어 둔다.
#  - 스레드 1개로 순차 처리(NAS 호출은 Lock 직렬화되므로 과도한 병렬은 무의미)
#  - 진행상황을 메모리에 기록하여 관리자가 진행률을 확인할 수 있다.
_THUMB_JOB = {
    "running": False,
    "total": 0,
    "done": 0,
    "images": 0,
    "videos": 0,
    "skipped": 0,
    "failed": 0,
    "stop": False,
    "started": "",
    "finished": "",
    "last": "",
}
_THUMB_JOB_LOCK = threading.Lock()
_THUMB_INDEX_FILE = BASE + "/db/thumb_index.json"

# ---------------------------------------------------------------------------
# [성능/안정] 썸네일 '지연 생성' 전용 워커 풀 — 사용자 요청 경로에서 분리
#   기존 문제: 캐시에 썸네일이 없으면 요청 처리 스레드가 **원본(동영상이면
#   영상 전체)을 NAS에서 통째로 받아** 즉석 생성했다. 폴더를 열면 사진 N장이
#   동시에 이 경로를 타 나스 대역폭이 포화 → 사진·행사 폴더가 '안 열리는'
#   현상이 발생했다.
#   해결: 즉석 생성을 **백그라운드 워커 풀**로 넘기고, 요청은 즉시 (썸네일 →
#   없으면 가벼운 플레이스홀더) 응답한다. 생성이 끝나면 다음 요청부터 실제
#   썸네일이 뜬다. 동시 실행 수를 제한해 나스를 절대 포화시키지 않는다.
# ---------------------------------------------------------------------------
_THUMB_GEN_POOL = ThreadPoolExecutor(max_workers=int(
    os.environ.get("TSAK_THUMB_WORKERS", "3")))
_THUMB_GEN_LOCK = threading.Lock()
_THUMB_GEN_PENDING = set()          # 생성 예약된 (year,title,name,sub) 키


def _thumb_gen_key(year, title, name, sub=""):
    return (str(year), str(title), _safe_name(name), str(sub or ""))


def _schedule_thumb_generation(year, title, name, sub=""):
    """썸네일 준비를 백그라운드로 예약(중복 방지). 요청을 절대 막지 않는다.

    워커는 (1) NAS 에 이미 있는 썸네일이면 로컬 캐시로 당겨오고,
           (2) 없으면 원본에서 생성한 뒤 로컬 캐시로 당겨온다.
    → 요청 경로는 로컬 디스크만 보고 즉시 응답한다(NAS 왕복 0회).
    """
    key = _thumb_gen_key(year, title, name, sub)
    with _THUMB_GEN_LOCK:
        if key in _THUMB_GEN_PENDING:
            return False
        _THUMB_GEN_PENDING.add(key)

    def _run():
        try:
            _thumb_sync_or_create(year, title, name, sub)
        except Exception as e:
            print("thumb gen bg fail", name, e)
        finally:
            with _THUMB_GEN_LOCK:
                _THUMB_GEN_PENDING.discard(key)

    try:
        _THUMB_GEN_POOL.submit(_run)
    except Exception:
        with _THUMB_GEN_LOCK:
            _THUMB_GEN_PENDING.discard(key)
    return True


def _thumb_sync_or_create(year, title, name, sub=""):
    """백그라운드: NAS 기존 썸네일을 로컬 캐시로 당기거나, 없으면 생성 후 당긴다."""
    tp = _ev_thumb_path(year, title, name, sub)
    # (1) NAS 에 이미 있으면 로컬 캐시로 복사(다음 요청부터 0ms).
    try:
        if NAS.exists(tp):
            _thumb_disk_put(year, title, name, sub, NAS.read_bytes(tp))
            return "synced"
    except Exception:
        pass
    # (2) 없으면 생성.
    try:
        _ev_spot_thumb(year, title, name, sub, _kind_of(name), 480)
    except Exception as e:
        print("thumb create bg fail", name, e)
    # (3) 생성 결과를 로컬 캐시로 당긴다.
    try:
        if NAS.exists(tp):
            _thumb_disk_put(year, title, name, sub, NAS.read_bytes(tp))
            return "created"
    except Exception:
        pass
    return "none"



def _ev_thumb_job_reset(total):
    with _THUMB_JOB_LOCK:
        _THUMB_JOB.update({
            "running": True, "total": total, "done": 0,
            "images": 0, "videos": 0, "skipped": 0, "failed": 0,
            "stop": False,
            "started": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "finished": "", "last": "",
        })


def _ev_thumb_job_inc(field, last=None):
    with _THUMB_JOB_LOCK:
        _THUMB_JOB["done"] = int(_THUMB_JOB.get("done", 0)) + 1
        _THUMB_JOB[field] = int(_THUMB_JOB.get(field, 0)) + 1
        if last:
            _THUMB_JOB["last"] = last


def _ev_thumb_job_finish():
    with _THUMB_JOB_LOCK:
        _THUMB_JOB["running"] = False
        _THUMB_JOB["finished"] = datetime.datetime.now().strftime(
            "%Y-%m-%d %H:%M:%S")


def _ev_thumb_job_state():
    with _THUMB_JOB_LOCK:
        return dict(_THUMB_JOB)


def _ev_media_files_with_meta(year, title, key, sub=""):
    """(파일명, sub경로) 목록 — 하위폴더까지 재귀 수집."""
    out = []
    fp = _ev_sub_dir(year, title, key, sub)
    if not fp or not NAS.exists(fp):
        return out
    try:
        r = NAS.list(fp)
    except Exception:
        return out
    for f in (r.get("files") or []):
        nm = f.get("name", "")
        if nm.startswith("."):
            continue
        if f.get("isdir"):
            child = f"{sub}/{nm}" if sub else nm
            out.extend(_ev_media_files_with_meta(year, title, key, child))
        else:
            out.append((nm, sub))
    return out


def _ev_spot_thumb(year, title, name, sub, kind, k, key="media",
                   assume_missing=False):
    """단일 파일 썸네일 생성. 반환: 'image' | 'video' | 'skip' | 'fail'.

    key: 행사 하위폴더 key — 'media'(사진+동영상) 외에 'expense'(영수증·증빙)도
    같은 썸네일 저장소를 공유한다. 썸네일 파일명에 key 접두어를 붙여 충돌 방지.

    assume_missing: 백필처럼 "썸네일이 없다"를 이미 확인한 경우 True.
      → 파일마다 하던 NAS exists 왕복(2회)을 건너뛴다. 6,900건 × 0.4초 ≈ 46분 절약.
    """
    try:
        if not assume_missing:
            if NAS.exists(_ev_thumb_path_k(year, title, key, name, sub)):
                # 이미 있음 → 로컬 디스크 캐시만 보강(예열)하고 skip.
                try:
                    _tk = _ev_thumb_key_k(key, name, sub)
                    if _thumb_disk_get(year, title, _tk) is None:
                        data = NAS.read_bytes(
                            _ev_thumb_path_k(year, title, key, name, sub))
                        _thumb_disk_put(year, title, _tk, data)
                except Exception:
                    pass
                return "skip"
            orig = _ev_find_file(year, title, key, name, sub)
        else:
            # 계획 단계에서 원본 목록을 이미 받아 왔다 → 경로만 조립.
            fp_dir = _ev_sub_dir(year, title, key, sub)
            orig = f"{fp_dir}/{_safe_name(name)}" if fp_dir else None
        if not orig:
            return "skip"
        if kind == "image":
            ok = _make_image_thumb3(
                NAS.read_bytes(orig), year, title, key, name, sub, max_side=k)
            return "image" if ok else "fail"
        if kind == "video":
            # 동영상은 NAS 원본을 임시로 받아 첫 프레임 추출
            import tempfile
            tmp = tempfile.NamedTemporaryFile(
                suffix=_ext_of(name), delete=False).name
            try:
                with open(tmp, "wb") as w:
                    w.write(NAS.read_bytes(orig))
                ok = _make_video_thumb2(tmp, year, title, name, sub, max_side=k)
                del ok
                return "video"
            finally:
                try:
                    os.unlink(tmp)
                except Exception:
                    pass
        return "skip"
    except Exception as e:
        print("spot thumb fail", name, e)
        return "fail"


# 썸네일 생성은 파일마다 `_ev_ensure_thumb_dir` 를 호출한다. 이것이 매번
#  NAS `exists` 왕복(≈0.2초)을 하면 6,900건 × 0.2초 = 23분을 순수 대기로 버린다.
#  한 번 확인한 (연도, 행사) 는 프로세스 수명 동안 기억한다(폴더는 사라지지 않음).
_THUMB_DIR_OK = set()
_THUMB_DIR_OK_LOCK = threading.Lock()


def _ev_ensure_thumb_dir(year, title):
    """썸네일 저장 폴더 보장(누락 시 생성). 결과를 프로세스 캐시."""
    ck = (str(year), str(title))
    with _THUMB_DIR_OK_LOCK:
        if ck in _THUMB_DIR_OK:
            return True
    tdir = _ev_thumb_dir(year, title)
    if NAS.exists(tdir):
        with _THUMB_DIR_OK_LOCK:
            _THUMB_DIR_OK.add(ck)
        return True
    try:
        _ev_mkdir_deep(tdir)
    except Exception as e:
        print("thumb dir fail", tdir, e)
    ok = NAS.exists(tdir)
    if ok:
        with _THUMB_DIR_OK_LOCK:
            _THUMB_DIR_OK.add(ck)
    return ok


def _ev_thumb_names_on_nas(year, title):
    """썸네일 폴더에 **이미 있는 파일명 집합** — NAS list 1회로 끝낸다.

    [성능 2026-10-29] 종전 백필은 파일마다 `NAS.exists` 를 호출해 썸네일이
    이미 있는 12,000여 건을 **전부 skip 하느라 20분 이상**을 낭비했다.
    폴더 목록 1회(=행사당 1콜)로 대체해 계획 단계를 수십 배 빠르게 만든다.
    """
    tdir = _ev_thumb_dir(year, title)
    out = set()
    try:
        if not NAS.exists(tdir):
            return out
        r = NAS.list(tdir)
        for f in (r.get("files") or []):
            if not f.get("isdir"):
                out.add(f.get("name", ""))
    except Exception:
        pass
    return out


def _ev_thumb_basename(name, sub=""):
    """`_ev_thumb_path_k(EVENT_MEDIA_KEY, ...)` 의 파일명 부분."""
    return _ev_thumb_key_k("media", name, sub).replace("/", "__") + ".jpg"


def _ev_backfill_plan(force=False):
    """백필 대상 계획 — [(year, title, name, sub, kind), ...]

    [개선 2026-10-29] 두 가지를 바꿨다.
      1) `force=False` 면 **썸네일이 없는 파일만** 큐에 넣는다.
         → 진행률(total)이 '실제 남은 일'을 뜻하게 되어 의미가 정확해진다.
      2) **누락이 많은 행사부터** 처리한다(내림차순).
         → 새로 등록된 대형 행사(사진 수천 장)가 뒤에서 몇 시간씩 기다리지
           않고 즉시 만들어진다. 화면에 사진이 빨리 뜨는 순서와 일치한다.
    """
    doc = _ev_doc()
    per_event = []
    for eid, e in doc.get("events", {}).items():
        year = e.get("year", "")
        title = e.get("title", "")
        if not year or not title:
            continue
        files = _ev_media_files_with_meta(year, title, "media")
        if not files:
            continue
        have = set() if force else _ev_thumb_names_on_nas(year, title)
        todo = []
        for nm, sub in files:
            kind = _kind_of(nm)
            if kind not in ("image", "video"):
                continue
            if not force and _ev_thumb_basename(nm, sub) in have:
                continue
            todo.append((year, title, nm, sub, kind))
        if todo:
            per_event.append(todo)
    per_event.sort(key=len, reverse=True)      # 큰 행사 먼저
    out = []
    for todo in per_event:
        out.extend(todo)
    return out


def _ev_backfill_thumbs_worker(max_side=480, force=False):
    """행사 사진/동영상 썸네일 백필(백그라운드)."""
    try:
        jobs = _ev_backfill_plan(force=force)
        # 썸네일 폴더가 없는 행사만 만들어 둔다(이미 있으면 NAS 왕복 0회).
        seen_ev = set()
        for (year, title, _nm, _sub, _kind) in jobs:
            k = (year, title)
            if k in seen_ev:
                continue
            seen_ev.add(k)
            _ev_ensure_thumb_dir(year, title)
        print("thumb backfill plan", {
            "jobs": len(jobs), "events": len(seen_ev), "force": force})
        _ev_thumb_job_reset(len(jobs))
        # [성능 2026-10-29] 순차 처리 시 실측 ~1.7초/건 → 6,900건이면 3시간+.
        #  NAS 연결 풀이 8개까지 동시 사용을 지원하므로 소수 병렬로 단축한다.
        #  (TSAK_THUMB_CONC 기본 4 — 나스·메모리 부하를 보며 조절 가능)
        try:
            conc = int(os.environ.get("TSAK_THUMB_CONC", "4"))
        except Exception:
            conc = 4
        conc = max(1, min(6, conc))

        def _one(item):
            """파일 1건 처리 — 예외는 여기서 흡수해 워커를 죽이지 않는다."""
            (year, title, nm, sub, kind) = item
            if _THUMB_JOB.get("stop"):
                return
            try:
                if force:
                    try:
                        NAS.delete(_ev_thumb_path(year, title, nm, sub))
                    except Exception:
                        pass
                res = _ev_spot_thumb(year, title, nm, sub, kind, max_side,
                                     assume_missing=not force)
                if res == "image":
                    _ev_thumb_job_inc("images", f"{title}/{nm}")
                elif res == "video":
                    _ev_thumb_job_inc("videos", f"{title}/{nm}")
                elif res == "skip":
                    _ev_thumb_job_inc("skipped")
                else:
                    _ev_thumb_job_inc("failed", f"{title}/{nm}")
            except Exception as e:
                print("backfill item fail", nm, e)
                _ev_thumb_job_inc("failed")

        if conc <= 1:
            for it in jobs:
                if _THUMB_JOB.get("stop"):
                    print("thumb backfill stopped by user",
                          _ev_thumb_job_state())
                    break
                _one(it)
        else:
            # 청크 단위로 끊어 돌려 중단 요청에 빠르게 반응시킨다.
            chunk = conc * 8
            for i in range(0, len(jobs), chunk):
                if _THUMB_JOB.get("stop"):
                    print("thumb backfill stopped by user",
                          _ev_thumb_job_state())
                    break
                with ThreadPoolExecutor(max_workers=conc) as ex:
                    list(ex.map(_one, jobs[i:i + chunk]))
        print("thumb backfill done", _ev_thumb_job_state())
    except Exception as e:
        print("thumb backfill worker fail", e)
    finally:
        _ev_thumb_job_finish()


def _ev_start_thumb_backfill(max_side=480, force=False):
    """이미 진행 중이면 시작하지 않는다."""
    with _THUMB_JOB_LOCK:
        if _THUMB_JOB.get("running"):
            return False
    t = threading.Thread(
        target=_ev_backfill_thumbs_worker,
        args=(max_side, force),
        daemon=True,
    )
    t.start()
    return True


# ============ 폴더 진입 시 예열(on-demand warm) ============
# 요구: "썸네일을 해당 폴더에 저장해 로딩속도를 획기적으로 개선하고, 최적화
# 폴더(.views)를 실시간으로 만들어 최적화 해상도 이미지를 자동 생성·저장한 뒤
# 그 내용을 불러온다." → 목록 응답 직후, 열려 있는 폴더의 파일들에 대해
# 백그라운드로 (썸네일 + 최적화본)을 미리 생성해 두어 첫 화면 로딩을 단축한다.
_EV_WARM = {"running": False, "total": 0, "done": 0, "thumbs": 0,
            "views": 0, "skipped": 0, "failed": 0, "key": ""}
_EV_WARM_LOCK = threading.Lock()


def _ev_warm_reset(total, key):
    with _EV_WARM_LOCK:
        _EV_WARM.update({"running": True, "total": total, "done": 0,
                         "thumbs": 0, "views": 0, "skipped": 0, "failed": 0,
                         "key": key})


def _ev_warm_inc(field):
    with _EV_WARM_LOCK:
        _EV_WARM["done"] = int(_EV_WARM.get("done", 0)) + 1
        _EV_WARM[field] = int(_EV_WARM.get(field, 0)) + 1


def _ev_warm_state():
    with _EV_WARM_LOCK:
        return dict(_EV_WARM)


def _ev_warm_worker(year, title, key, jobs, make_views):
    """열린 폴더의 파일들에 대해 썸네일(+최적화본)을 미리 생성한다."""
    try:
        for (nm, sub, kind) in jobs:
            try:
                res = _ev_spot_thumb(year, title, nm, sub, kind, 480, key=key)
                if res in ("image", "video"):
                    _ev_warm_inc("thumbs")
                elif res == "skip":
                    _ev_warm_inc("skipped")
                else:
                    _ev_warm_inc("failed")
                # 최적화(1600px) 본은 이미지만, 없을 때만 생성.
                if make_views and kind == "image":
                    try:
                        vp = _ev_view_path_k(year, title, key, nm, sub)
                        if not NAS.exists(vp):
                            orig = _ev_find_file(year, title, key, nm, sub)
                            if orig:
                                _make_image_view3(
                                    NAS.read_bytes(orig), year, title, key,
                                    nm, sub)
                                _ev_warm_inc("views")
                    except Exception:
                        pass
            except Exception as e:
                print("warm item fail", nm, e)
                _ev_warm_inc("failed")
        print("warm done", _ev_warm_state())
    except Exception as e:
        print("warm worker fail", e)
    finally:
        with _EV_WARM_LOCK:
            _EV_WARM["running"] = False


def _ev_warm_folder(year, title, key, sub, make_views=True):
    """열린 폴더(하위폴더 포함)의 이미지/동영상 예열을 백그라운드로 시작.

    [성능/안정] 파일 목록 스캔(`_ev_media_files_with_meta` → 파일별 NAS.exists)
      을 **백그라운드 스레드**로 옮긴다. 기존에는 요청 처리 스레드가 NAS 왕복을
      동기로 수십~수백 회 하느라 폴더 열기가 지연됐다. 이제 호출 즉시 반환한다.
    """
    with _EV_WARM_LOCK:
        if _EV_WARM.get("running"):
            return False

    def _scan_and_warm():
        try:
            jobs = []
            for nm, s in _ev_media_files_with_meta(year, title, key, sub):
                k = _kind_of(nm)
                if k in ("image", "video"):
                    jobs.append((nm, s, k))
            if not jobs:
                return
            _ev_warm_reset(len(jobs), key)
            _ev_warm_worker(year, title, key, jobs, make_views)
        except Exception as e:
            print("warm scan fail", e)
            with _EV_WARM_LOCK:
                _EV_WARM["running"] = False

    # 선점 플래그(중복 방지) 후 스캔 스레드 시작.
    with _EV_WARM_LOCK:
        _EV_WARM["running"] = True
    try:
        threading.Thread(target=_scan_and_warm, daemon=True).start()
    except Exception:
        with _EV_WARM_LOCK:
            _EV_WARM["running"] = False
        return False
    return True


def _ev_find_file(year, title, key, name, sub=""):
    fp_dir = _ev_sub_dir(year, title, key, sub)
    if not fp_dir:
        return None
    safe = _safe_name(name)
    fp = f"{fp_dir}/{safe}"
    return fp if NAS.exists(fp) else None


# ---- WebP 최적본(_optimized) 우선 서빙 -------------------------------
# tools/optimize_event_webp.py 가 원본 옆 `_optimized/<이름>.webp` 로 재압축본을
# 만들어 두면, 원본 대신 이 WebP 를 서빙한다(평균 ~85% 절감, 예: 5.1GB→0.8GB).
#  · 원본은 절대 건드리지 않는다(비파괴). 매핑은 파일명 stem 기준.
#  · 없으면 원본 폴백 → 배치가 중간에 중단돼도 서비스는 항상 정상.
_OPT_SUBDIR = "_optimized"
_OPT_DONE_EXT = {".jpg", ".jpeg", ".png", ".bmp", ".tif", ".tiff"}


def _opt_path_for(orig_path):
    """원본 NAS 경로 → _optimized 미러 webp 경로(없으면 None)."""
    if not orig_path or "/" not in orig_path:
        return None
    d, base = orig_path.rsplit("/", 1)
    if "." not in base:
        return None
    if _ext_of(base) not in _OPT_DONE_EXT:
        return None
    stem = base.rsplit(".", 1)[0]
    return "%s/%s/%s.webp" % (d, _OPT_SUBDIR, stem)


def _ev_opt_path(year, title, key, name, sub=""):
    """행사 항목 파일의 _optimized webp 경로(존재하지 않으면 None)."""
    fp = _ev_find_file(year, title, key, name, sub)
    op = _opt_path_for(fp) if fp else None
    if op and NAS.exists(op):
        return op
    return None


# ---- 썸네일 로컬 디스크 캐시 -----------------------------------------------
# NAS 는 원격(HTTPS)이라 썸네일을 매 요청마다 NAS 에서 읽으면 왕복 ~0.9s 가
# 걸린다. 백필 후 로컬 디스크에 캐시해 두면 브라우저가 이미 가진 캐시까지
# 고려해 첫 로딩이 ~0.02s 로 단축된다.
_THUMB_DISK_DIR = os.path.join(STATE_ROOT, ".thumb_cache")
_THUMB_DISK_LOCK = threading.Lock()


def _thumb_disk_path(year, title, name, sub=""):
    key = _ev_thumb_key(name, sub)
    safe = re.sub(r"[^0-9A-Za-z_.\-가-힣]", "_", f"{_ev_safe(year)}__{_ev_safe(title)}__{key}")
    return f"{_THUMB_DISK_DIR}/{safe}.jpg"


def _thumb_disk_get(year, title, name, sub=""):
    """로컬 캐시에서 썸네일 바이트 반환. 없으면 None."""
    p = _thumb_disk_path(year, title, name, sub)
    try:
        if os.path.exists(p):
            with open(p, "rb") as f:
                return f.read()
    except Exception:
        pass
    return None


def _thumb_disk_put(year, title, name, sub, data):
    try:
        os.makedirs(_THUMB_DISK_DIR, exist_ok=True)
        p = _thumb_disk_path(year, title, name, sub)
        tmp = p + ".tmp"
        with open(tmp, "wb") as f:
            f.write(data)
        os.replace(tmp, p)
    except Exception:
        pass


_THUMB_PLACEHOLDER = {"data": None}


def _thumb_placeholder():
    """썸네일이 아직 없을 때 즉시 응답할 가벼운 회색 플레이스홀더 JPEG.

    폴더를 열 때 원본(동영상 전체)을 다운로드하느라 멈추는 것을 막는다.
    백그라운드 생성이 끝나면 다음 요청부터 실제 썸네일이 뜬다.
    """
    if _THUMB_PLACEHOLDER["data"] is not None:
        return _THUMB_PLACEHOLDER["data"]
    try:
        import io
        from PIL import Image
        im = Image.new("RGB", (16, 16), (222, 222, 228))
        buf = io.BytesIO()
        im.save(buf, format="JPEG", quality=60)
        _THUMB_PLACEHOLDER["data"] = buf.getvalue()
    except Exception:
        _THUMB_PLACEHOLDER["data"] = b""
    return _THUMB_PLACEHOLDER["data"]


def _thumb_get(year, title, name, sub="", build_missing=True):
    """썸네일 바이트 반환 — **로컬 디스크 캐시에서만**(NAS 왕복 0회).

    [성능/안정] 요청 경로에서는 NAS 를 전혀 건드리지 않는다. 로컬 캐시에
      없으면 즉시 None 을 돌려주고(NAS.exists 조차 하지 않음), 준비(기존
      썸네일 동기화 또는 생성)는 백그라운드 워커가 처리한다. → 사진 N장이
      동시에 요청돼도 서버 응답이 절대 지연/정체되지 않는다.
    """
    data = _thumb_disk_get(year, title, name, sub)
    if data is not None:
        return data
    if build_missing:
        try:
            _schedule_thumb_generation(year, title, name, sub)
        except Exception:
            pass
    return None



def _ev_collect_under(base, rel_prefix="", recursive=True, max_entries=None):
    """base 폴더 아래 파일들을 rel 경로와 함께 수집 (rel_prefix 기준).

    각 항목에 **size** 를 함께 담는다. ZIP 용량을 사전에 계산해
    메모리 폭발(OOM)을 막기 위한 것이다. max_entries 로 상한을 둘 수 있다.
    """
    if not base or not NAS.exists(base):
        return []
    paths = []

    def walk(p, rel):
        if max_entries and len(paths) >= max_entries:
            raise RuntimeError("too many entries: >%d" % max_entries)
        r = NAS.list(p)
        if not r.get("ok"):
            return
        for f in r["files"]:
            nm = f["name"]
            if nm.startswith("."):
                continue
            child = f"{p}/{nm}"
            if f.get("isdir"):
                if recursive:
                    walk(child, f"{rel}/{nm}")
            else:
                paths.append({
                    "path": child,
                    "rel": f"{rel}/{nm}",
                    "size": int(f.get("size", 0) or 0),
                })
    walk(base, rel_prefix or base.rsplit("/", 1)[-1])
    return paths


def _ev_collect_paths(year, title, key, sub="", recursive=True):
    """항목 폴더(하위경로)의 파일 경로 목록(ZIP용). rel은 하위폴더명 유지."""
    return _ev_collect_under(_ev_sub_dir(year, title, key, sub),
                             recursive=recursive)


def _ev_zip_paths(year, title):
    """행사 전체 폴더의 파일 경로 목록 (ZIP용)."""
    base = _ev_dir(year, title)
    if not NAS.exists(base):
        return []
    paths = []

    def walk(p, rel):
        r = NAS.list(p)
        if not r.get("ok"):
            return
        for f in r["files"]:
            nm = f["name"]
            if nm.startswith("."):
                continue
            child = f"{p}/{nm}"
            if f.get("isdir"):
                walk(child, f"{rel}/{nm}")
            else:
                paths.append({"path": child, "rel": f"{rel}/{nm}"})
    walk(base, _ev_safe(title))
    return paths


def _ev_ext_ok(name):
    return _ext_of(name)


def _ev_build_zip(paths, files=None):
    """[사용금지] ZIP 전체를 RAM 에 만든다 — OOM 사고의 원인.

    호출부가 없음을 확인했으나, 재유입 시 사고가 재발하므로 남겨두지 않고
    스트리밍 버전으로 강제 위임한다(_ev_build_zip_to_file 참고).
    """
    raise RuntimeError(
        "_ev_build_zip 은 OOM 위험으로 제거되었습니다. "
        "_ev_build_zip_to_file + _ev_stream_file 을 사용하세요.")


# ⚠ [사고 재발 방지] 위 _ev_build_zip 은 ZIP 전체를 RAM 에 만든 뒤 한 번에
#   반환한다. 사진 폴더 하나(2.3GB)를 다운로드하면 zip 버퍼 + getvalue() 복사
#   + wfile.write() 로 같은 데이터가 2~3벌 메모리에 동시에 존재해 OOM Killer 가
#   python3 프로세스를 죽였다(실측 anon-rss 4.9GB, 가용 7.9GB).
#   → 아래 스트리밍 버전을 쓰고, zip 은 **디스크 임시파일**에 만든다.
_EV_ZIP_CHUNK = 1024 * 256


def _ev_zip_looks_binary(rel):
    """압축을 시도하지 않을 확장자(이미 압축된 미디어) — CPU/시간 절약."""
    ext = os.path.splitext(str(rel))[1].lower()
    return ext in (
        ".jpg", ".jpeg", ".png", ".gif", ".webp", ".heic", ".heif",
        ".mp4", ".mov", ".m4v", ".avi", ".mkv", ".3gp", ".wmv",
        ".zip", ".gz", ".bz2", ".xz", ".7z", ".rar",
    )


def _ev_collect_zip_entries(paths, files=None):
    """ZIP 에 넣을 (rel, size, fetch_fn) 목록. fetch_fn 은 바이트 반환."""
    out = []
    if files is not None:
        for it in files:
            out.append((it["rel"], len(it["data"]), (lambda b=it["data"]: b)))
        return out
    # ⚠ [OOM 사고 핵심 원인] 예전에는 get_info(path)['size'] 를 믿었다.
    #   그런데 NAS 는 **폴더**에 대해 size=항목수(예: 16062)를 돌려주고 isdir
    #   플래그도 주지 않는다. 그래서 5.19GB 폴더가 "16KB"로 계산되어 용량
    #   검사(probe)를 통과했고, 16,062개 파일을 하나씩 받아 메모리가 폭발했다.
    #   → 이제 **list() 가 이미 알려준 size** 를 신뢰하고, 없을 때만 조회한다.
    hits = []
    for it in paths:
        fp = it["path"]
        size = it.get("size")
        if size is None:
            try:
                info = NAS.get_info(fp)
                if info.get("isdir"):
                    continue
                size = int(info.get("size", 0) or 0)
            except Exception:
                continue
        size = int(size or 0)
        hits.append((it["rel"], fp, size))
    for rel, fp, size in hits:
        out.append((rel, size, (lambda p=fp: NAS.read_bytes(p))))
    return out


def _ev_build_zip_to_file(paths, dest, files=None, max_bytes=None):
    """NAS 파일들을 **디스크 임시파일**에 ZIP 으로 쓴다. RAM 사용은 청크 크기뿐.

    max_bytes: 넘으면 중단(RuntimeError). 디스크가 꽉 차는 사고 방지.
    반환: (엔트리수, 건너뛴수, 총바이트)
    """
    import zipfile
    entries = _ev_collect_zip_entries(paths, files)
    # [핵심] 쓰기 **전에** 총 용량을 검사한다 — 다운로드를 시작조차 하지 않는다.
    if max_bytes:
        planned = sum(s for (_r, s, _f) in entries)
        if planned > max_bytes:
            raise RuntimeError(
                "zip too large: %d bytes (limit %d)" % (planned, max_bytes))
    n = skipped = total = 0
    with zipfile.ZipFile(dest, "w", zipfile.ZIP_STORED) as z:
        for rel, size, fetch in entries:
            try:
                data = fetch()
            except Exception:
                skipped += 1
                continue
            if not data:
                skipped += 1
                continue
            comp = (zipfile.ZIP_STORED if _ev_zip_looks_binary(rel)
                    else zipfile.ZIP_DEFLATED)
            try:
                z.writestr(zipfile.ZipInfo(rel), data, compress_type=comp)
            except Exception:
                # 이름이 너무 길거나 특수문자 문제 → 건너뛴다(전체를 죽이지 않음).
                skipped += 1
                continue
            n += 1
            total += len(data)
            del data
    return n, skipped, total


def _ev_stream_file(self, fp, ctype, download_name=None, chunk=_EV_ZIP_CHUNK):
    """디스크 파일을 **청크 단위**로 응답에 흘려보낸다(RAM 상승 없음)."""
    size = os.path.getsize(fp)
    self.send_response(200)
    self.send_header("Content-Type", ctype)
    self.send_header("Content-Length", str(size))
    if download_name:
        try:
            fn = urllib.parse.quote(str(download_name))
        except Exception:
            fn = str(download_name)
        self.send_header(
            "Content-Disposition", f"attachment; filename*=UTF-8''{fn}")
    self._cors()
    self.end_headers()
    with open(fp, "rb") as f:
        while True:
            b = f.read(chunk)
            if not b:
                break
            self.wfile.write(b)


def _ev_roster_html(year, title):
    """참가자 명단을 무인양품풍 + 컬러풀 디자인 HTML로 출력 (인쇄/저장용)."""
    doc = _ev_doc()
    e = doc.get("events", {}).get(_ev_id(year, title), {})
    # [요구] 명단 출력 시 '인가시 등록대' 대신 '활동등록대'를 표시한다.
    #   (원본 캐시 보호를 위해 dict 복사 후 표시용 필드 주입)
    attendees = []
    for _a in e.get("attendees", []):
        if isinstance(_a, dict):
            _a2 = dict(_a)
            _ev_attendee_view(_a2)
            attendees.append(_a2)
        else:
            attendees.append(_a)
    place = e.get("place", "")
    period = e.get("period", "") or e.get("date", "")
    desc = e.get("desc", "")
    access = _ev_access_map(_ev_id(year, title))

    # 범스카우트 색채(프랑스 국기: 블루·화이트·레드) 중심 팔레트
    palette = ["#1B4F9C", "#D62828", "#2E7D32", "#B7791F", "#00838F",
               "#6D4C41", "#AD1457", "#283593", "#5B2C8D", "#37474F"]

    def esc(s):
        return (str(s or "")
                .replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))

    rows = []
    for i, a in enumerate(attendees, 1):
        ident = re.sub(r"[^0-9]", "", str(a.get("number") or a.get("phone") or ""))
        visited = ident in access
        color = palette[(i - 1) % len(palette)]
        roles = a.get("roles") or ([a.get("role")] if a.get("role") else [])
        role_chips = "".join(
            f'<span style="display:inline-block;margin:1px 3px 1px 0;padding:2px 8px;'
            f'border-radius:10px;background:{color}22;color:{color};font-size:11px;'
            f'font-weight:700">{esc(r)}</span>' for r in roles
        )
        vbox = (
            '<span style="display:inline-block;width:16px;height:16px;line-height:16px;'
            'text-align:center;border-radius:4px;background:#2E7D32;color:#fff;'
            'font-size:11px;font-weight:800">V</span>'
            if visited else
            '<span style="display:inline-block;width:16px;height:16px;border:1px solid #ccc;'
            'border-radius:4px"></span>'
        )
        rows.append(f"""
      <tr style="border-bottom:1px solid #eee">
        <td style="padding:8px 6px;color:#888;font-size:12px">{i}</td>
        <td style="padding:8px 6px;text-align:center">{vbox}</td>
        <td style="padding:8px 6px;font-weight:700">{esc(a.get('name',''))}</td>
        <td style="padding:8px 6px;font-size:13px;color:#555">{esc(a.get('unitText') or a.get('unit',''))}</td>
        <td style="padding:8px 6px;font-size:12px">{esc(a.get('gender',''))}</td>
        <td style="padding:8px 6px;font-size:12px">{esc(a.get('phone',''))}</td>
        <td style="padding:8px 6px;font-size:12px">{esc(a.get('email',''))}</td>
        <td style="padding:8px 6px">{role_chips}</td>
      </tr>""")

